window.HOEREN_TESTS[29] = {"id":"behoerden-und-dokumente","name":"Behörden und Dokumente","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Hallo Frau Müller, hier ist das Bürgeramt. Ihr neuer Personalausweis ist fertig — Sie können ihn ab Montag abholen. Bitte bringen Sie nicht nur Geld mit, sondern Geld und den alten Personalausweis. 28 Euro 80, in bar oder mit Karte. Den neuen Personalausweis haben wir hier, den müssen Sie nicht mitbringen. Den alten nehmen wir entgegen. Bis Montag, bitte Ausweis und Geld nicht vergessen.","gender":"f","q":"Was muss Frau Müller mitbringen?","opts":["Geld und den alten Personalausweis.","Nur Geld.","Den neuen Personalausweis."],"correct":0},{"transcript":"Achtung, eine wichtige Information vom Finanzamt. Die Steuererklärung 2024 müssen Sie bis zum 31. Juli abgeben — sonst gibt es Bußgeld. Online geht es bis Mitternacht des letzten Tages, also 31. Juli bis Mitternacht. Wer per Post schickt, muss schneller sein — der Brief muss spätestens am 30. Juli ankommen, nicht am 31. Der 30. Juni ist schon vorbei, das ist nicht die Frist. Bitte nicht vergessen!","gender":"m","q":"Wann ist die Frist für Online-Abgabe?","opts":["30. Juli.","30. Juni.","31. Juli bis Mitternacht."],"correct":2},{"transcript":"Hi Schatz, hier ist Anna. Pass auf, ich war heute bei der Ausländerbehörde wegen meinem neuen Aufenthaltstitel. Es war Chaos — drei Stunden Wartezeit! Aber jetzt ist alles fertig. Nächstes Mal sollten wir online einen Termin machen — das geht schneller. Ich habe dafür heute den ganzen Vormittag verloren.","gender":"f","q":"Was empfiehlt Anna für nächstes Mal?","opts":["Online einen Termin machen.","Wieder ohne Termin gehen.","Gar nicht hingehen."],"correct":0},{"transcript":"Liebe Bürger, das Standesamt hat ab nächstem Monat neue Öffnungszeiten. Statt 8 bis 16 Uhr sind wir nun von 8 bis 18 Uhr da. Donnerstag ist langer Tag, da bis 19 Uhr — nicht Montag und nicht Samstag. Wochenende bleiben wir geschlossen. Heiratswillige sollten frühzeitig einen Termin vereinbaren — wir sind oft ausgebucht. Montag ist ein normaler Tag bis 18 Uhr.","gender":"f","q":"Wann ist der lange Tag?","opts":["Montag.","Donnerstag.","Samstag."],"correct":1},{"transcript":"Hallo Tom, hier ist das Standesamt. Du hast einen Termin für deine Hochzeit am 15. Mai — wir haben einen Fehler gemacht und einem anderen Paar denselben Tag gegeben. Tut uns sehr leid! Bitte ruf zurück, wir bieten dir 22. Mai oder 5. Juni als Alternative. Danke für dein Verständnis!","gender":"f","q":"Was hat sich geändert?","opts":["Die Hochzeit wird abgesagt.","Der Termin am 15. Mai geht nicht mehr.","Der Preis ist anders."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Welcher Termin ist an welchem Tag? Wählen Sie für jeden Tag einen Buchstaben (a–i).","lines":[{"speaker":"Vater","gender":"m","text":"Hallo! Die Mappe für die Ämter liegt schon auf dem Tisch."},{"speaker":"Mutter","gender":"f","text":"Die Woche ist voll. Wir gehen am besten der Reihe nach."},{"speaker":"Vater","gender":"m","text":"Wir sind montags beim Bürgeramt. Der Personalausweis ist abgelaufen."},{"speaker":"Mutter","gender":"f","text":"Um acht öffnet die Tür. Liegt das neue Foto schon oben?"},{"speaker":"Vater","gender":"m","text":"Das Foto steckt in der Mappe. Müssen wir diese Woche auch zum Arbeitsamt?"},{"speaker":"Mutter","gender":"f","text":"Nein. Das Arbeitsamt kommt erst im nächsten Monat."},{"speaker":"Vater","gender":"m","text":"Noch ein schwerer Gang wartet am Dienstag."},{"speaker":"Mutter","gender":"f","text":"Wir gehen zum Finanzamt. Die Steuern vom letzten Jahr machen mir Sorgen."},{"speaker":"Vater","gender":"m","text":"Ich nehme alle Belege mit. Was steht am Mittwoch in der Werkstatt?"},{"speaker":"Mutter","gender":"f","text":"Das Auto hat TÜV. Die Hauptuntersuchung beginnt um halb neun."},{"speaker":"Vater","gender":"m","text":"Brauchen wir auch einen Termin bei der Ausländerbehörde?"},{"speaker":"Mutter","gender":"f","text":"Nein. Ein Visum brauchen wir nicht. Die Ausländerbehörde fällt diese Woche weg."},{"speaker":"Vater","gender":"m","text":"Für das Baby fehlt am Donnerstag noch ein Papier."},{"speaker":"Mutter","gender":"f","text":"Wir holen die Geburtsurkunde beim Standesamt."},{"speaker":"Vater","gender":"m","text":"Die Krankenkasse wartet am Freitag auf uns. Wir brauchen eine neue Karte."},{"speaker":"Mutter","gender":"f","text":"Nimm die Mappe mit. Danach ist die Woche geschafft."}],"options":[{"letter":"a","text":"TÜV — Hauptuntersuchung"},{"letter":"b","text":"Polizei — Verlustanzeige"},{"letter":"c","text":"Ausländerbehörde"},{"letter":"d","text":"Arbeitsamt"},{"letter":"e","text":"Bürgeramt — Personalausweis"},{"letter":"f","text":"Gericht"},{"letter":"g","text":"Standesamt — Geburtsurkunde"},{"letter":"h","text":"Krankenkasse"},{"letter":"i","text":"Finanzamt — Steuern"}],"items":[{"person":"Montag","correct":"e"},{"person":"Dienstag","correct":"i"},{"person":"Mittwoch","correct":"a"},{"person":"Donnerstag","correct":"g"},{"person":"Freitag","correct":"h"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Beamter","gender":"m","text":"Guten Tag, welche Dokumente möchten Sie beantragen — Personalausweis, Reisepass oder Führerschein?"},{"speaker":"Kunde","gender":"m","text":"Einen neuen Reisepass. Mein alter ist abgelaufen. Den Personalausweis habe ich noch, Führerschein auch."},{"speaker":"Beamter","gender":"m","text":"Foto bitte, und 60 Euro. Für den Reisepass, nicht für den Führerschein."},{"speaker":"Kunde","gender":"m","text":"Foto habe ich. Hier. Also Reisepass, nicht Personalausweis."},{"speaker":"Beamter","gender":"m","text":"Alles da. Der Reisepass dauert etwa zwei Wochen. Hier ist die Quittung."}],"q":"Was beantragt der Kunde?","opts":["Personalausweis.","Reisepass.","Führerschein."],"correct":1},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, wie lange dauert es — 4 Wochen, 2 Wochen, oder bekomme ich das Dokument sofort?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Normal 4 Wochen. Mit Express-Service 2 Wochen, aber 32 Euro extra. Sofort geht es leider nicht."},{"speaker":"Kundin","gender":"f","text":"4 Wochen ist zu lang, sofort wäre schön, aber wenn das nicht geht: Express dann, also 2 Wochen."},{"speaker":"Mitarbeiterin","gender":"f","text":"Gerne, Express in 2 Wochen. Nicht 4 Wochen und nicht sofort. Die 32 Euro extra notiere ich."},{"speaker":"Kundin","gender":"f","text":"Gut, 2 Wochen. Hier ist die Karte für die extra 32 Euro."}],"q":"Wie lange dauert es?","opts":["4 Wochen.","Sofort.","2 Wochen."],"correct":2},{"lines":[{"speaker":"Sekretärin","gender":"f","text":"Guten Tag, Termin beim Finanzamt — wann passt? Diese Woche oder nächste Woche?"},{"speaker":"Kunde","gender":"m","text":"Diese Woche, wenn möglich. Nächste Woche bin ich im Urlaub."},{"speaker":"Sekretärin","gender":"f","text":"Mittwoch oder Donnerstag, jeweils 14 Uhr. Nächste Woche wäre auch frei, aber Sie wollen diese Woche."},{"speaker":"Kunde","gender":"m","text":"Mittwoch — Donnerstag habe ich eine Sitzung. Also Mittwoch um 14 Uhr, nicht Donnerstag und nicht nächste Woche."},{"speaker":"Sekretärin","gender":"f","text":"Notiert, Mittwoch 14 Uhr. Bitte Unterlagen mitbringen."}],"q":"Wann ist der Termin?","opts":["Donnerstag um 14 Uhr.","Mittwoch um 14 Uhr.","Nächste Woche."],"correct":1},{"lines":[{"speaker":"Frau","gender":"f","text":"Guten Tag, ich habe meinen Personalausweis verloren. Nicht den Pass, den habe ich noch. Die Bankkarte auch."},{"speaker":"Polizist","gender":"m","text":"Wann und wo? Pass, Ausweis oder Bankkarte — ich muss das genau notieren."},{"speaker":"Frau","gender":"f","text":"Heute Morgen im Bus. Nur der Personalausweis, nicht der Pass und nicht die Bankkarte."},{"speaker":"Polizist","gender":"m","text":"Ich notiere alles. Sie bekommen einen Verlustschein für einen neuen Personalausweis."},{"speaker":"Frau","gender":"f","text":"Danke, dann gehe ich danach zum Bürgeramt."}],"q":"Was hat die Frau verloren?","opts":["Den Personalausweis.","Den Pass.","Die Bankkarte."],"correct":0},{"lines":[{"speaker":"Kunde","gender":"m","text":"Guten Tag, ich möchte mich ummelden — neue Adresse. Nicht neu anmelden in der Stadt, ich wohne schon lange hier. Die Wohnung kündige ich nicht."},{"speaker":"Mitarbeiterin","gender":"f","text":"Alte und neue Adresse bitte. Ummeldung wegen Umzug, verstanden."},{"speaker":"Kunde","gender":"m","text":"Alt: Goethestraße 5. Neu: Schillerstraße 22, Wohnung 4B. Also Umzug, keine neue Anmeldung."},{"speaker":"Mitarbeiterin","gender":"f","text":"Ab wann gilt das? Ab dem Einzugstag?"},{"speaker":"Kunde","gender":"m","text":"Ab kommenden Montag, das ist mein Einzugstag. Die alte Wohnung kündige ich später, nicht heute."}],"q":"Was macht der Kunde?","opts":["Er meldet sich neu an.","Er kündigt die Wohnung.","Er meldet seinen Umzug an."],"correct":2}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Frau Klein, einer Bürgeramt-Mitarbeiterin. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Frau Klein, Sie arbeiten seit 18 Jahren im Bürgeramt. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Klein","gender":"f","text":"Eigentlich wollte ich Polizistin werden. Aber die Ausbildung war zu hart für mich, ich bin nicht so sportlich. Im Bürgeramt arbeite ich auch mit Menschen — andere Arbeit, aber ähnlich befriedigend."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie hauptsächlich?"},{"speaker":"Klein","gender":"f","text":"Personalausweise und Pässe machen. Umzüge anmelden. Geburtsurkunden ausstellen. Auch Wahllisten verwalten. Eigentlich alles, was die Bürger an Dokumenten brauchen."},{"speaker":"Reporter","gender":"m","text":"Was hat sich in den 18 Jahren am meisten verändert?"},{"speaker":"Klein","gender":"f","text":"Die Digitalisierung. Vor 18 Jahren war alles Papier, alles per Hand. Heute haben wir Computer-Systeme. Manche Termine kann man jetzt online buchen. Vieles geht auch ohne uns. Mein Beruf wird in einigen Jahren vielleicht ganz anders aussehen."},{"speaker":"Reporter","gender":"m","text":"Welche Kunden sind besonders schwierig?"},{"speaker":"Klein","gender":"f","text":"Wütende Kunden, die lange warten mussten. Manche schreien sofort, wenn sie dran sind. Aber meistens sind die Leute höflich, vor allem wenn ich ihnen helfen kann. Ein Lächeln und Geduld lösen fast alles."},{"speaker":"Reporter","gender":"m","text":"Was machen Sie in der Freizeit?"},{"speaker":"Klein","gender":"f","text":"Gärtnern! Ich habe einen Garten, wo ich viel Zeit verbringe. Den ganzen Tag muss ich Formulare ausfüllen, aber im Garten habe ich Frische und Stille. Ganz anders."}],"items":[{"q":"In den letzten 18 Jahren hat sich wenig verändert.","correct":"nein"},{"q":"Sie macht hauptsächlich Personalausweise und Pässe.","correct":"ja"},{"q":"Frau Klein wollte ursprünglich Polizistin werden.","correct":"ja"},{"q":"Wütende Kunden sind die Mehrheit.","correct":"nein"},{"q":"In ihrer Freizeit gärtnert sie gern.","correct":"ja"}]}]};
